import React, { useEffect, useRef, useState } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Points, PointMaterial, Float, MeshDistortMaterial } from '@react-three/drei';
import { Box, Typography, Button, Container, Chip } from '@mui/material';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import * as random from 'maath/random/dist/maath-random.esm';
gsap.registerPlugin(ScrollTrigger);

// Starfield
function StarField(props) {
  const ref = useRef();
  const [sphere] = useState(() =>
    random.inSphere(new Float32Array(3200), { radius: 1.5 })
  );
  useFrame((state, delta) => {
    ref.current.rotation.x -= delta / 10;
    ref.current.rotation.y -= delta / 15;
  });
  return (
    <group rotation={[0, 0, Math.PI / 4]}>
      <Points ref={ref} positions={sphere} stride={3} frustumCulled={false} {...props}>
        <PointMaterial transparent color="#667eea" size={0.005} sizeAttenuation depthWrite={false} />
      </Points>
    </group>
  );
}

// Animated torus
function AnimatedTorus() {
  const meshRef = useRef();
  useFrame((state) => {
    meshRef.current.rotation.x = state.clock.elapsedTime * 0.3;
    meshRef.current.rotation.y = state.clock.elapsedTime * 0.2;
  });
  return (
    <Float speed={2} rotationIntensity={1} floatIntensity={2}>
      <mesh ref={meshRef} scale={1.5}>
        <torusGeometry args={[1, 0.3, 32, 100]} />
        <MeshDistortMaterial color="#764ba2" distort={0.4} speed={2} roughness={0.2} metalness={0.8} />
      </mesh>
    </Float>
  );
}

// Floating icosahedron
function FloatingGeo() {
  const meshRef = useRef();
  useFrame((state) => {
    meshRef.current.rotation.x = Math.sin(state.clock.elapsedTime * 0.5) * 0.5;
    meshRef.current.rotation.z = Math.cos(state.clock.elapsedTime * 0.3) * 0.5;
  });
  return (
    <Float speed={1.5} floatIntensity={1.5}>
      <mesh ref={meshRef} position={[2.5, 0, -1]} scale={0.6}>
        <icosahedronGeometry args={[1, 1]} />
        <MeshDistortMaterial color="#f093fb" distort={0.3} speed={3} wireframe />
      </mesh>
    </Float>
  );
}

function FloatingOctahedron() {
  const meshRef = useRef();
  useFrame((state) => {
    meshRef.current.rotation.y = state.clock.elapsedTime * 0.8;
  });
  return (
    <Float speed={2.5} floatIntensity={2}>
      <mesh ref={meshRef} position={[-2.5, -0.5, -1]} scale={0.5}>
        <octahedronGeometry args={[1, 0]} />
        <MeshDistortMaterial color="#667eea" distort={0.5} speed={2} metalness={1} roughness={0} />
      </mesh>
    </Float>
  );
}

const Home = () => {
  const heroRef = useRef();
  const titleRef = useRef();
  const subtitleRef = useRef();
  const ctaRef = useRef();
  const tagsRef = useRef([]);
  const scrollHintRef = useRef();

  useEffect(() => {
    const tl = gsap.timeline({ delay: 0.2 });

    tl.fromTo(titleRef.current,
      { y: 80, opacity: 0, skewX: -5 },
      { y: 0, opacity: 1, skewX: 0, duration: 1, ease: 'power4.out' }
    )
    .fromTo(subtitleRef.current,
      { y: 40, opacity: 0 },
      { y: 0, opacity: 1, duration: 0.8, ease: 'power3.out' }
    , '-=0.5')
    .fromTo(tagsRef.current,
      { y: 30, opacity: 0, scale: 0.8 },
      { y: 0, opacity: 1, scale: 1, duration: 0.5, stagger: 0.1, ease: 'back.out(1.7)' }
    , '-=0.3')
    .fromTo(ctaRef.current,
      { y: 20, opacity: 0 },
      { y: 0, opacity: 1, duration: 0.6, ease: 'power3.out' }
    , '-=0.2')
    .fromTo(scrollHintRef.current,
      { y: 20, opacity: 0 },
      { y: 0, opacity: 1, duration: 0.5 }
    );

    // Scroll hint bounce
    gsap.to(scrollHintRef.current, {
      y: 10,
      repeat: -1,
      yoyo: true,
      duration: 1.2,
      ease: 'power1.inOut'
    });

    // Parallax on scroll
    gsap.to('.hero-canvas', {
      scrollTrigger: {
        trigger: heroRef.current,
        start: 'top top',
        end: 'bottom top',
        scrub: 1
      },
      y: 150,
      opacity: 0.3
    });

    return () => ScrollTrigger.getAll().forEach(t => t.kill());
  }, []);

  const tags = ['React.js', 'Node.js', 'TypeScript', 'MongoDB', 'AWS', 'Docker'];

  return (
