          <StarField />
          <AnimatedTorus />
          <FloatingGeo />
          <FloatingOctahedron />
        </Canvas>
      </Box>

      {/* Gradient overlays */}
      <Box sx={{
        position: 'absolute', inset: 0, zIndex: 1,
