      }} />

      {/* Content */}
      <Container maxWidth="lg" sx={{ position: 'relative', zIndex: 2, pt: { xs: 10, md: 0 } }}>
        <Box sx={{ maxWidth: '700px' }}>
          {/* Greeting chip */}
          <Chip
            label="👋 Available for opportunities"
            sx={{
              mb: 3,
              background: 'rgba(102,126,234,0.1)',
              border: '1px solid rgba(102,126,234,0.3)',
              color: '#667eea',
              fontFamily: '"Space Mono", monospace',
              fontSize: '0.75rem',
              fontWeight: 600,
              backdropFilter: 'blur(10px)'
            }}
          />

          <Typography
            ref={titleRef}
            variant="h1"
            sx={{
              fontSize: { xs: '3rem', sm: '4.5rem', md: '6rem' },
              fontWeight: 900,
              fontFamily: '"Clash Display", "Space Grotesk", sans-serif',
              lineHeight: 1.05,
              mb: 2,
              background: 'linear-gradient(135deg, #1a1a2e 0%, #302b63 50%, #764ba2 100%)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              backgroundClip: 'text'
            }}
          >
            Hi, I'm<br />
            <Box
              component="span"
              sx={{
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 50%, #f093fb 100%)',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
                backgroundClip: 'text'
              }}
            >
              Param Parikh
            </Box>
          </Typography>

          <Typography
            ref={subtitleRef}
            sx={{
              fontSize: { xs: '1.1rem', md: '1.4rem' },
              color: '#5a6080',
              fontFamily: '"Space Mono", monospace',
              mb: 4,
              lineHeight: 1.7
            }}
          >
            Full Stack Developer crafting <Box component="span" sx={{ color: '#667eea', fontWeight: 700 }}>scalable web apps</Box> and <Box component="span" sx={{ color: '#764ba2', fontWeight: 700 }}>clean architectures</Box> with modern technologies.
          </Typography>

          {/* Skill tags */}
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 5 }}>
            {tags.map((tag, i) => (
              <Chip
                key={tag}
                ref={el => tagsRef.current[i] = el}
                label={tag}
                sx={{
                  background: 'rgba(255,255,255,0.7)',
