                  fontFamily: '"Space Mono", monospace',
                  fontSize: '0.7rem',
                  backdropFilter: 'blur(10px)',
                  color: '#4a4a7a',
                  transition: 'all 0.3s ease',
                  '&:hover': {
                    background: 'rgba(102,126,234,0.15)',
